    public static function key(string $source):string{return 'mail_settings_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {$english=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as $source=>$translation)$out[self::key($source)]=$english?$translation:$source;return $out;}
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return $messages[self::key($source)];
        if(str_contains($source,' · ')){return implode(' · ',array_map(static fn(string $part):string=>self::text($part,$messages),explode(' · ',$source)));}
        foreach(['Vorstand','Presse','Newsletter']as $channel)if(str_starts_with($source,$channel.': '))return self::text($channel,$messages).': '.self::text(substr($source,strlen($channel)+2),$messages);
        return GeneralSettingsMessages::text($source,$messages);
    }
